function s(i){if(!i)return"—";const n=new Date(i);if(Number.isNaN(n.getTime()))return String(i);const e=t=>String(t).padStart(2,"0");return`${n.getFullYear()}-${e(n.getMonth()+1)}-${e(n.getDate())} ${e(n.getHours())}:${e(n.getMinutes())}`}function r(i,n){let e=i;if(e==null||e===""){if(!n)return"";const t=new Date(n).getTime()-Date.now();if(Number.isNaN(t))return"";e=t>=0?Math.floor(t/864e5):-Math.ceil(-t/864e5)}return e=Number(e),Number.isNaN(e)?"":e<0?`已过期 ${-e} 天`:e===0?"不足 1 天":`剩余 ${e} 天`}function u(i){return{deployed:"success",success:"success",issued:"success",active:"success",skipped:"info",draft:"info",idle:"info",pending:"warning",running:"warning",issuing:"warning",failed:"danger",disabled:"info"}[i]||"info"}function a(i){return{deployed:"已部署",issued:"已签发",draft:"草稿",issuing:"签发中",failed:"失败",success:"成功",skipped:"已跳过",pending:"等待",running:"执行中",idle:"空闲",active:"启用",disabled:"停用",triggered:"已触发"}[i]||i||"—"}export{a,s as f,r,u as s};
